6	import { AgentInput, BashInput, FileReadInput, GlobInput, GrepInput } from '@anthropic-ai/claude-agent-sdk/sdk-tools';
7	import Anthropic from '@anthropic-ai/sdk';
8	import * as l10n from '@vscode/l10n';
9	import type { ChatSimpleToolResultData, ChatTerminalToolInvocationData } from 'vscode';
10	import { URI } from '../../../../util/vs/base/common/uri';
11	import { ChatSubagentToolInvocationData, ChatToolInvocationPart, MarkdownString } from '../../../../vscodeTypes';
12	import { ClaudeToolNames, ExitPlanModeInput, LSInput } from './claudeTools';
13	
14	// #region Tool Result Content Extraction
15	
16	/**
17	 * Extracts text content from a tool result's content field.
18	 * Tool results can be a string, an array of content blocks, or undefined.
19	 */
20	function extractToolResultContent(content: Anthropic.Messages.ToolResultBlockParam['content']): string {
21		if (!content) {
22			return '';
23		}
24		if (typeof content === 'string') {
25			return content;
26		}
27		// Array of content blocks - extract text from each
28		return content
29			.filter((block): block is Anthropic.Messages.TextBlockParam => block.type === 'text')
30			.map(block => block.text)
31			.join('\n');
32	}
33	
34	// #endregion
35	
36	// #region Tool Invocation Completion Handlers
37	
38	/**
39	 * Completes a tool invocation by populating toolSpecificData with the result.
40	 * This enables VS Code's chat UI to display tool outputs.
41	 */
42	export function completeToolInvocation(
43		toolUse: Anthropic.Beta.Messages.BetaToolUseBlock,
44		toolResult: Anthropic.Messages.ToolResultBlockParam,
45		invocation: ChatToolInvocationPart
46	): void {
47		const resultContent = extractToolResultContent(toolResult.content);
48	
49		switch (toolUse.name as ClaudeToolNames) {
50			case ClaudeToolNames.Bash:
51				completeBashInvocation(invocation, toolUse, resultContent);
52				break;
53			case ClaudeToolNames.Read:
54			case ClaudeToolNames.LS:
55				completeReadInvocation(invocation, toolUse, resultContent);
56				break;
57			case ClaudeToolNames.Glob:
58			case ClaudeToolNames.Grep:
59				completeSearchInvocation(invocation, toolUse, resultContent);
60				break;
61			case ClaudeToolNames.Edit:
62			case ClaudeToolNames.MultiEdit:
63			case ClaudeToolNames.Write:
64			case ClaudeToolNames.TodoWrite:
65				// These tools have their own UI handling (edit diffs, todo list)
66				break;
67			case ClaudeToolNames.Task:
68				completeTaskInvocation(invocation, resultContent);
69				break;
70			default:
71				completeGenericInvocation(invocation, toolUse, resultContent);
72				break;
73		}
74	}
75	
76	/**
77	 * Completes a bash tool invocation with terminal-specific output formatting.
78	 * Parses exit code from output and formats for ChatTerminalToolInvocationData.
79	 */
80	function completeBashInvocation(
81		invocation: ChatToolInvocationPart,
82		toolUse: Anthropic.Beta.Messages.BetaToolUseBlock,
83		resultContent: string
84	): void {
85		// Parse exit code from the end of the result (format: "Exit code: X" or similar patterns)
86		const exitCodeMatch = /(?:exit code|exited with)[:=\s]*(\d+)/i.exec(resultContent);
87		const exitCode = exitCodeMatch ? parseInt(exitCodeMatch[1], 10) : undefined;
88	
89		// Remove exit code line from output for cleaner display
90		let text = resultContent;
91		if (exitCode !== undefined) {
92			text = resultContent.replace(/(?:exit code|exited with)[:=\s]*\d+\s*$/i, '').trimEnd();
93		}
94	
95		// Convert \n to \r\n for proper terminal display
96		text = text.replace(/\n/g, '\r\n');
97	
98		const toolSpecificData: ChatTerminalToolInvocationData = {
99			commandLine: {
100				original: (toolUse.input as BashInput)?.command ?? '',
101			},
102			language: 'bash',
103			state: exitCode !== undefined ? { exitCode } : undefined,
104			output: text ? { text } : undefined
105		};
106		invocation.toolSpecificData = toolSpecificData;
107	}
108	
109	/**
110	 * Completes a read/ls tool invocation with simple input/output display.
111	 */
112	function completeReadInvocation(
113		invocation: ChatToolInvocationPart,
114		toolUse: Anthropic.Beta.Messages.BetaToolUseBlock,
115		resultContent: string
116	): void {
117		if (!resultContent) {
118			return;
119		}
120	
121		const input = toolUse.name === ClaudeToolNames.LS
122			? (toolUse.input as LSInput)?.path ?? ''
123			: (toolUse.input as FileReadInput)?.file_path ?? '';
124	
125		const toolSpecificData: ChatSimpleToolResultData = {
126			input,
127			output: resultContent
128		};
129		invocation.toolSpecificData = toolSpecificData;
130	}
131	
132	/**
133	 * Completes a glob/grep tool invocation with simple input/output display.
134	 */
135	function completeSearchInvocation(
136		invocation: ChatToolInvocationPart,
137		toolUse: Anthropic.Beta.Messages.BetaToolUseBlock,
138		resultContent: string
139	): void {
140		if (!resultContent) {
141			return;
142		}
143	
144		const input = toolUse.name === ClaudeToolNames.Glob
145			? (toolUse.input as GlobInput)?.pattern ?? ''
146			: (toolUse.input as GrepInput)?.pattern ?? '';
147	
148		const toolSpecificData: ChatSimpleToolResultData = {
149			input,
150			output: resultContent
151		};
152		invocation.toolSpecificData = toolSpecificData;
153	}
154	
155	/**
156	 * Completes a Task tool invocation by setting the result on its ChatSubagentToolInvocationData.
157	 * The toolSpecificData was already populated by formatTaskInvocation with description/agentName/prompt;
158	 * this adds the result text from the subagent's execution.
159	 */
160	function completeTaskInvocation(
161		invocation: ChatToolInvocationPart,
162		resultContent: string
163	): void {
164		if (invocation.toolSpecificData instanceof ChatSubagentToolInvocationData) {
165			invocation.toolSpecificData.result = resultContent;
166		}
167	}
168	
169	/**
170	 * Generic completion handler for tools without specific formatting.
171	 * Displays input arguments and output as plain text.
172	 */
173	function completeGenericInvocation(
174		invocation: ChatToolInvocationPart,
175		toolUse: Anthropic.Beta.Messages.BetaToolUseBlock,
176		resultContent: string
177	): void {
178		if (!resultContent) {
179			return;
180		}
181	
182		const toolSpecificData: ChatSimpleToolResultData = {
183			input: toolUse.input ? JSON.stringify(toolUse.input, null, 2) : '',
184			output: resultContent
185		};
186		invocation.toolSpecificData = toolSpecificData;
187	}
188	
189	// #endregion
