/**
 * Extracts the `parentToolUseId` for a subagent by scanning its messages for the
 * first assistant message carrying a string `parent_tool_use_id`. This identifies
 * the Agent/Task tool_use block in the parent session that spawned the subagent.
 *
 * The field may appear either on the raw `SessionMessage` or on its inner `message`
 * content, so both locations are checked. Non-string values are ignored, and
 * `undefined` is returned when no valid string value is found.
 */
function extractParentToolUseId(messages: readonly SessionMessage[]): string | undefined {
	for (const msg of messages) {
		if (msg.type !== 'assistant') {
			continue;
		}

		const candidates: unknown[] = [];
		const inner = msg.message;
		if (inner !== null && typeof inner === 'object' && 'parent_tool_use_id' in inner) {
			candidates.push((inner as { parent_tool_use_id?: unknown }).parent_tool_use_id);
		}
		candidates.push((msg as { parent_tool_use_id?: unknown }).parent_tool_use_id);

		for (const candidate of candidates) {
			if (typeof candidate === 'string') {
				return candidate;
			}
		}
	}

	return undefined;
}

